class Solution:
    def kWeakestRows(self, mat: list[list[int]], k: int) -> list[int]:
        import heapq
        def count_ones(row: list[int]) -> int:
            l, r = 0, len(row)
            while l < r:
                mid = (l + r) // 2
                if row[mid] == 1:
                    l = mid + 1
                else:
                    r = mid
            return l
        pq = []
        for i, row in enumerate(mat):
            cnt = count_ones(row)
            heapq.heappush(pq, (-cnt, -i))
            if len(pq) > k:
                heapq.heappop(pq)
        ans = []
        while pq:
            _, idx = heapq.heappop(pq)
            ans.append(-idx)
        return ans[::-1]

