    public int nthSuperUglyNumber(int n, int[] primes) {
        int k = primes.length;
        int[] ugly = new int[n];
        ugly[0] = 1;
        int[] idx = new int[k];
        long[] next = new long[k];
        for (int j = 0; j < k; j++) next[j] = primes[j];
        for (int i = 1; i < n; i++) {
            long minVal = next[0];
            for (int j = 1; j < k; j++) {
                if (next[j] < minVal) minVal = next[j];
            }
            ugly[i] = (int) minVal;
            for (int j = 0; j < k; j++) {
                if (next[j] == minVal) {
                    idx[j]++;
                    next[j] = (long) ugly[idx[j]] * primes[j];
                }
            }
        }
        return ugly[n - 1];
    }
}

