class Solution {
    public int furthestBuilding(int[] heights, int bricks, int ladders) {
        return dfs(heights, 0, bricks, ladders);
    }
    private int dfs(int[] h, int idx, int b, int l) {
        if (idx == h.length - 1) return idx;
        int diff = h[idx + 1] - h[idx];
        if (diff <= 0) return dfs(h, idx + 1, b, l);
        int res = idx;
        if (b >= diff) res = Math.max(res, dfs(h, idx + 1, b - diff, l));
        if (l > 0) res = Math.max(res, dfs(h, idx + 1, b, l - 1));
        return res;
    }
}

