        Arrays.sort(hand);
        boolean[] used = new boolean[hand.length];
        for (int i = 0; i < hand.length; i++) {
            if (used[i]) continue;
            int cur = hand[i];
            used[i] = true;
            int count = 1;
            for (int j = i + 1; j < hand.length && count < groupSize; j++) {
                if (!used[j] && hand[j] == cur + 1) {
                    cur = hand[j];
                    used[j] = true;
                    count++;
                }
            }
            if (count < groupSize) return false;
        }
        return true;
    }
}

