    public boolean isPossibleDivide(int[] nums, int k) {
        if (nums.length % k != 0) return false;
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) map.put(num, map.getOrDefault(num, 0) + 1);
        int[] sorted = new int[map.size()];
        int idx = 0;
        for (int key : map.keySet()) sorted[idx++] = key;
        Arrays.sort(sorted);
        for (int num : sorted) {
            int cnt = map.get(num);
            if (cnt > 0) {
                for (int i = 0; i < k; i++) {
                    int next = num + i;
                    if (map.getOrDefault(next, 0) < cnt) return false;
                    map.put(next, map.get(next) - cnt);
                }
            }
        }
        return true;
    }
