        Arrays.sort(tokens);
        return dfs(tokens, 0, tokens.length - 1, power, 0);
    }
    private int dfs(int[] t, int l, int r, int p, int s) {
        if (l > r) return s;
        int max = s;
        if (p >= t[l]) {
            max = Math.max(max, dfs(t, l + 1, r, p - t[l], s + 1));
        } else if (s > 0 && l < r) {
            max = Math.max(max, dfs(t, l, r - 1, p + t[r], s - 1));
        }
        return max;
    }
}

