        score = max_score = 0
        while l <= r:
            if power >= tokens[l]:
                power -= tokens[l]
                l += 1
                score += 1
                max_score = max(max_score, score)
            elif score > 0:
                power += tokens[r]
                r -= 1
                score -= 1
            else:
