class Solution {
    public String predictPartyVictory(String senate) {
        Queue<Integer> r = new LinkedList<>();
        Queue<Integer> d = new LinkedList<>();
        int n = senate.length();
        for (int i = 0; i < n; i++) {
            if (senate.charAt(i) == 'R') r.offer(i);
            else d.offer(i);
        }
        while (!r.isEmpty() && !d.isEmpty()) {
            int rIdx = r.poll();
            int dIdx = d.poll();
            if (rIdx < dIdx) {
                r.offer(rIdx + n);
            } else {
                d.offer(dIdx + n);
            }
        }
        return r.isEmpty() ? "Dire" : "Radiant";
    }
}

