            } else {
                int cnt = map.get(h);
                if (cnt == 1) map.remove(h);
                else map.put(h, cnt - 1);
            }
            int curMax = map.lastKey();
            if (curMax != prevMax) {
                res.add(Arrays.asList(x, curMax));
                prevMax = curMax;
            }
        }
        return res;
    }
